        oil_line(ans, at, 10, 20 + (k * 60), 200, 40, 0, 1, -1, 0, 10, 55 + (k * 60), 210, 55 + (k * 60), 14, 14, 6, 0, 0, 0, 0, 0, 0, 0, 0, 0);
